__bundle_register("lua.utils", function(require, _LOADED, __bundle_register, __bundle_modules)
local TableUtils = require("lua.utils-table")

local Utils = {}

function Utils.round(num)
    return num + (2^52 + 2^51) - (2^52 + 2^51)
end

function Utils:firstToUpper(str)
    return (str:gsub("^%l", string.upper))
end

function Utils.trim(str)
    return str:gsub("^%s*", ""):gsub("%s*$", "")
 end

function Utils.copy(obj)
    if type(obj) ~= 'table' then return obj end
    local res = {}
    for k, v in pairs(obj) do res[Utils.copy(k)] = Utils.copy(v) end
    return res
end

-- SEPERATOR IS NOT REGEX ESCAPED
function Utils.split(s, sep)
    local tokens = {}

    local seperator = sep or " "
    local pattern = string.format("([^%s]+)", seperator)
    string.gsub(s, pattern, function(t) table.insert(tokens, t) end)

    return tokens
end

-- Throttle func to not run more than once each delay. delay in seconds
function Utils.throttle(func, delay)
    local lastInvokeTime = 0

    return function (...)
        local timeNow = Time.time
        if timeNow - lastInvokeTime < delay then
            return
        end
        lastInvokeTime = timeNow
        return func(...)
    end
end

-- Debounce func to run only once after repeated calls within delay. delay in seconds
function Utils.debounce(func, delay)
    local waitHandle = nil
    return function (...)
        if waitHandle ~= nil then
            Wait.stop(waitHandle)
        end
        local args = {...}
        waitHandle = Wait.time(function() func(unpack(args)) end, delay)
    end
end

function Utils.containerContainsObject(container, objToFind)
    if objToFind == nil or container == nil then
      return false
    end

    for _, obj in pairs(container.getObjects()) do
      if obj.getGUID() == objToFind.getGUID() then
        return true
      end
    end

    return false
end

function Utils.getObjectsWithTagsOnBoard(tags)
    return TableUtils.filter(getObjectsWithAnyTags(tags), function(obj)
        local pos = obj.getPosition()
        local w = Setup.width[SETTINGS.boardsize]
        local h = Setup.height[SETTINGS.boardsize]
        return math.abs(pos.x) <= w /2 and math.abs(pos.z) <= h /2
      end)
end

function Utils.isCleanLoad()
  for _, obj in pairs(getObjectFromGUID(GUIDS["place_gamemode_zone"]).getObjects()) do
    if obj.hasTag("GamemodeCard") and obj.getLock() then
      return false
    end
  end
  return true
end


return Utils
end)
__bundle_register("lua.utils-table", function(require, _LOADED, __bundle_register, __bundle_modules)
local TableUtils = {}

function TableUtils.keys(tbl)
    local keys = {}
    local n = 0

    for k, v in pairs(tbl) do
        n = n + 1
        keys[n] = k
    end
    return keys
end

function TableUtils.sortedKeys(tbl, sortFunc)
    local keys = TableUtils.keys(tbl)
    if sortFunc == nil then
        sortFunc = function(a,b)
            return a < b
        end
    end
    return table.sort(keys, function (a, b)
        return sortFunc(tbl[a], tbl[b])
    end)
end

function TableUtils.last(tbl)
    return tbl[#tbl]
end

function TableUtils.values(tbl)
    local vals = {}
    local n = 0

    for k, v in pairs(tbl) do
        n = n + 1
        vals[n] = v
    end
    return vals
end

function TableUtils.hasValue(tbl, val)
    for k, value in pairs(tbl) do
        if value == val then
            return true
        end
    end

    return false
end

function TableUtils.any(tbl)
    for i, element in ipairs(tbl) do
        return true
    end
    return false
end

function TableUtils.all(tbl, func)
    for i, element in pairs(tbl) do
        if not func(element) then
            return false
        end
    end
    return true
end

function TableUtils.some(tbl, func)
    for i, element in pairs(tbl) do
        if func(element) then
            return true
        end
    end
    return false
end

function TableUtils.len(tbl)
    local count = 0
    for i, element in pairs(tbl) do
        count = count + 1
    end
    return count
end

function TableUtils.count(tbl, func)
    local count = 0
    for i, element in pairs(tbl) do
        if func(element, i) then
            count = count + 1
        end
    end
    return count
end

function TableUtils.getKeyByVal(tbl, val)
    for k, v in pairs(tbl) do
        if v == val then
            return k
        end
    end

    return nil
end

function TableUtils.getIdx(tbl, val)
    for idx, v in ipairs(tbl) do
        if v == val then
            return idx
        end
    end

    return 0
end

function TableUtils.filter(tbl, func)
    local out = {}
    for k, v in pairs(tbl) do
        if func(v, k) then
            table.insert(out, v)
        end
    end
    return out
end

function TableUtils.filterMap(tbl, filter)
    local out = {}
    for k, v in pairs(tbl) do
        if filter(v, k) then
            out[k] = v
        end
    end
    return out
end

function TableUtils.map(table, func)
    local out = {}
    for k, v in pairs(table) do
        out[k] = func(v, k)
    end
    return out
end

function TableUtils.find(table, func)
    for k, v in pairs(table) do
        if func(v) then return v end
    end
    return nil
end

function TableUtils.findIndex(table, func)
    for k, v in pairs(table) do
        if func(v) then return k end
    end
    return nil
end

function TableUtils.reduce(table, func, opts)
    opts = opts or {}
    local acc = opts.acc or 0
    for _, v in pairs(table) do
        acc = func(acc, v)
    end
    return acc
end

function TableUtils.shuffle(tbl)
    for i = #tbl, 2, -1 do
		local j = math.random(i)
		tbl[i], tbl[j] = tbl[j], tbl[i]
	end

    return tbl
end

function TableUtils.reverse(table)
    local out = {}
    for ix = #table, 1, -1 do
        table.insert(out, table[ix])
    end
    return out
end

function TableUtils.reversePairs(table)
    local out = {}
    local keys = TableUtils.keys(table)
    local len = #keys
    local ix = len + 1
    return function ()
        ix = ix -1
        if ix == 0 then
            return nil
        end
        local key = keys[ix]
        return key, table[key]
    end
end

-- FIXME: THIS CODE DOESNT WORK CORRECTLY
function TableUtils.tableContains(table, value)
    if table == nil then
      return false
    end

    for i, val in ipairs(table) do
      if type(val) == "table" and type(value) == "table" then
          return JSON.encode(val) == JSON.encode(value)
      end

      return val == value
    end

    return false
end


return TableUtils

end)
__bundle_register("lua.utils-events", function(require, _LOADED, __bundle_register, __bundle_modules)
local TableUtils = require("lua.utils-table")

local EventUtils = {
    listeners = {}
}

-- guid of the object for listeners attached to an object, nil for global
function EventUtils.register(event, listener, guid)
    if EventUtils.listeners[event] == nil then
        EventUtils.listeners[event] = {}
    end
    table.insert(EventUtils.listeners[event], {listener = listener, guid = guid})

    -- what if the event already exists due to bad code?
    -- we should transition legacy code to use this system
    if _G[event] == nil then
        _G[event] = function(...)
            for ix, obj in ipairs(EventUtils.getListeners(event)) do
                obj.listener({...})
            end
        end
    end
end

-- TODO: Use this when deleting objects
function EventUtils.unregister(event, listener)
    local listeners = EventUtils.listeners[event]
    local idx = TableUtils.findIndex(listeners, function(v) return v.listener == listener end)
    if idx ~= nil then
        table.remove(listeners, idx)
    else
        log("Tried to unregister event listener for event '" .. event .. "', but the listener was not found.")
    end
end
function EventUtils.unregisterByGuid(event, guid)
    local listeners = EventUtils.listeners[event]
    local idx = TableUtils.findIndex(listeners, function(v) return v.guid == guid end)
    if idx ~= nil then
        table.remove(listeners, idx)
    else
        log("Tried to unregister event listeners for event '" .. event .. "' on object '" .. guid .."', but no listeners were not found.")
    end
end


function EventUtils.getListeners(event)
    return EventUtils.listeners[event]
end

return EventUtils
end)
__bundle_register("lua.terrain", function(require, _LOADED, __bundle_register, __bundle_modules)
local EventUtils = require("lua.utils-events")

local aoeScaleX = 4.54
local aoeScaleZ = 4.54
local hoveredObjects = {}
local terrainAoeImages = {
  ["Weirwood Tree"] = "https://steamusercontent-a.akamaihd.net/ugc/2527165944742958879/5C431B81FBCCF1A670F98B932DCD7331FD8B2ED6/",
  ["Corpse Pile"] = "https://steamusercontent-a.akamaihd.net/ugc/2527165944779800819/F593DD104551F683657E59024479C2FEAABDD0C0/"
}

local function spawnAOE(object)
  local aoeImage = terrainAoeImages[object.getName()]

  if aoeImage == nil then
      return
  end

  local aoe = spawnObject({
    type = "Custom_Token",
    position = {object.getPosition().x, 1.6, object.getPosition().z},
    rotation = object.getRotation(),
    scale = {aoeScaleX, 1, aoeScaleZ},
    sound = false
  })
  aoe.setCustomObject(
    {
      image = aoeImage,
      thickness = 0.1,
      merge_distance = 15,
      stackable = false
    }
  )

  aoe.setColorTint({1,1,1,0})
  aoe.locked = true
  aoe.interactable = false
  object.setVar("aoe", aoe)

  Wait.frames(function() aoe.highlightOn(SETTINGS.rulerColorTint) end, 3)
end

local function clearAOE(object)
  if object == nil then
      return
  end

  hoveredObjects[object.getGUID()] = false

  local aoe = object.getVar("aoe")

  if aoe then
    aoe.destruct()
    object.setVar("aoe", nil)
  end
end

local function checkMouseLeave(object)
  for _, player in ipairs(Player.getPlayers()) do
    local holdingObjects = player.getHoldingObjects()
    local hoveredObject = player.getHoverObject()
    if holdingObjects == nil then
      holdingObjects = {}
    end
    if hoveredObject ~= nil then
      table.insert(holdingObjects, hoveredObject)
    end

    for __, heldObject in ipairs(holdingObjects) do
      if heldObject ~= nil and heldObject.getGUID() == object.getGUID() then
        local aoe = object.getVar("aoe")

        if aoe then
          aoe.setPosition({object.getPosition().x, 1.6, object.getPosition().z})
          aoe.setRotation(object.getRotation())
        end

        Wait.frames(function() checkMouseLeave(object) end, 2)

        return
      end
    end
  end

  clearAOE(object)
  object.highlightOff()
  hoveredObjects[object.getGUID()] = false
end


local onObjectDestroy = function(params)
  local object = unpack(params)
  if object and hoveredObjects and hoveredObjects[object.getGUID()] then
    clearAOE(object)
  end
end
EventUtils.register("onObjectDestroy", onObjectDestroy)

local onObjectHover = function(params)
  local player_color, object = unpack(params)
  if object == nil or not object.hasTag("Terrain") then
    return
  end

  local guid = object.getGUID()

  if not hoveredObjects[guid] then
      hoveredObjects[guid] = true
      spawnAOE(object)
      Wait.frames(function() checkMouseLeave(object) end, 2)
  end

end
EventUtils.register("onObjectHover", onObjectHover)

end)
__bundle_register("lua.tacticsBoard", function(require, _LOADED, __bundle_register, __bundle_modules)
local TableUtils = require("lua.utils-table")
local Utils = require("lua.utils")
local EventUtils = require("lua.utils-events")
local UiUtil = require("lua.utils-ui")

local TacticsBoard = {
    specialTactics = {
        Blue = nil,
        Red = nil
    }
}
local TacticsUi = {}

function TacticsBoard.placeNCU(obj, zone)
  local zoneName = TableUtils.getKeyByVal(GUIDS["tactics_zones"], zone.guid)
  if zoneName ~= nil then
      zoneName = Utils:firstToUpper(zoneName)
  end

  if Utils.containerContainsObject(zone, obj) then
      local portrait = obj.getGMNotes()
      local color = obj.getVar("owner")
      TacticsUi.placeNCU(zoneName, portrait, color)
  end
end

function TacticsBoard.removeNCU(obj, zone)
  local zoneName = TableUtils.getKeyByVal(GUIDS["tactics_zones"], zone.guid)

  if zoneName then
      zoneName = Utils:firstToUpper(zoneName)
  end

  if TableUtils.some(zone.getObjects(), function(o) return o.hasTag("NCU") end) then
      return
  end

  TacticsUi.removeNCU(zoneName)
end


local onEnter_TacticsZone = function(params)
    local zone, obj = unpack(params)
    if not obj.hasTag("NCU") then
        return
    end
    if not TableUtils.hasValue(GUIDS["tactics_zones"], zone.guid) then
        return
    end
    Wait.condition(function() TacticsBoard.placeNCU(obj, zone) end, function() return obj.resting end)
end
EventUtils.register("onObjectEnterZone", onEnter_TacticsZone)

local onLeave_TacticsZone = function(params)
    local zone, obj = unpack(params)
    if not TableUtils.hasValue(GUIDS["tactics_zones"], zone.guid) then
      return
    end
    Wait.condition(function() TacticsBoard.removeNCU(obj, zone) end, function() return obj.resting end)
end
EventUtils.register("onObjectLeaveZone", onLeave_TacticsZone)


local switchFirstPlayerMarker = function()
  local firstPlayer = getObjectFromGUID(GUIDS["first_player_throne"]) or getObjectFromGUID(GUIDS["first_player_standee"])
  if firstPlayer then
    local oldPosition = firstPlayer.getPosition()
    firstPlayer.setPositionSmooth({oldPosition.x, oldPosition.y, oldPosition.z*-1}, false, true)
    firstPlayer.rotate({0, 180, 0})
  end
end

local function endRound(round)
  for _, obj in pairs(gameObjects) do
      if obj.onEndRound ~= nil then
        obj:onEndRound()
      end
  end

  for guid, location in pairs(ncuPositions) do
    if location ~= nil then
      local ncu = getObjectFromGUID(guid)

      if ncu ~= nil then
        ncu.setPositionSmooth(location.position, false, true)
        if ncu.tag == "Card" then --don't flip cards back over
          local z = ncu.getRotation().z

          if z-180 < -1 or z-180 > 1 then
            z = location.rotation.z
          end

          ncu.setRotation({location.rotation.x, location.rotation.y, z})
        else
          ncu.setRotation(location.rotation)
        end
      end
    end
  end

  for _, guid in pairs(TableUtils.values(GUIDS["ncu_zone_resting"])) do
    for _, obj in ipairs(getObjectFromGUID(guid).getObjects()) do
      if obj.type == "Tile" then
        obj.setPositionSmooth(obj.getPosition() + Vector({0, 0.3, 0}))
      end
    end
  end

  switchFirstPlayerMarker()
  broadcastToAll("Round " .. round)
  currentRound = round
  TacticsUi.updateRound()
end

local onEnter_RoundZone = function(params)
    local zone, obj = unpack(params)
    if not TableUtils.hasValue(GUIDS["tactics_round"], zone.guid) then
        return
    end
    if obj.getName() ~= "Round" then
        return
    end
    local roundNumber = TableUtils.getIdx(GUIDS["tactics_round"], zone.guid)

    Wait.condition(function()
      endRound(roundNumber)
    end, function()
        return obj.resting
    end)
end
EventUtils.register("onObjectEnterZone", onEnter_RoundZone)


local onEnter_NCURestingZone = function(params)
    local zone, obj = unpack(params)
    if not TableUtils.hasValue(GUIDS["ncu_zone_resting"], zone.guid) then
        return
    end
    if not obj.hasTag("NCU") and not obj.hasTag("NCUcard") then
        return
    end

    Wait.condition(function()
        if ncuPositions[obj.guid] == nil then
            ncuPositions[obj.guid] = {
                position = obj.getPosition(),
                rotation = obj.getRotation()
            }
        end
    end, function()
        return obj.resting
    end)
end
EventUtils.register("onObjectEnterZone", onEnter_NCURestingZone)


local onEnter_FirstPlayerZone = function(params)
    local zone, obj = unpack(params)
    if not TableUtils.hasValue(GUIDS["tactics_first_player"], zone.guid) then
        return
    end
    if obj.getName() ~= "First Player" then
        return
    end
    local zoneColor = TableUtils.getKeyByVal(GUIDS["tactics_first_player"], zone.guid)
    if firstPlayerColor == zoneColor then
      return
    end
    Wait.condition(function()
        if not Utils.containerContainsObject(zone, obj) then
            return
        end
        firstPlayerColor = zoneColor
        local playerID = UiUtil.getPlayerName(zoneColor)
        broadcastToAll(playerID .. " is now first player", zoneColor)
        TacticsUi.updateFirstPlayer()
    end, function ()
        return obj.resting
    end)
end
EventUtils.register("onObjectEnterZone", onEnter_FirstPlayerZone)


function TacticsUi.updateFirstPlayer()
  UI.setAttribute("tacticsPanelBottom__RoundOverlay", "image", firstPlayerColor .. "Zone")
  UI.setAttribute("tacticsPanelSide__RoundOverlay", "image", firstPlayerColor .. "Zone")
end

function TacticsUi.updateRound()
  UI.setAttribute("tacticsPanelBottom__Round", "image", "Round" .. currentRound)
  UI.setAttribute("tacticsPanelSide__Round", "image", "Round" .. currentRound)
end

function TacticsUi.placeNCU(zone, portrait, color)
  if zone == nil then
    return
  end

  if portrait then
    UI.setAttribute("tacticsPanelBottom__".. zone, "image", string.upper(portrait))
    UI.setAttribute("tacticsPanelSide__".. zone, "image", string.upper(portrait))
  end

  if color then
    UI.setAttribute("tacticsPanelBottom__" .. zone .. "Overlay", "image", color .. "Zone")
    UI.setAttribute("tacticsPanelSide__" .. zone .. "Overlay", "image", color .. "Zone")
  end
end

function TacticsUi.removeNCU(zone)
    UI.setAttribute("tacticsPanelBottom__".. zone, "image", TacticsBoard.specialTactics[zone] or zone)
    UI.setAttribute("tacticsPanelSide__".. zone, "image", TacticsBoard.specialTactics[zone] or zone)

    UI.setAttribute("tacticsPanelBottom__" .. zone .. "Overlay", "image", "BlankZone")
    UI.setAttribute("tacticsPanelSide__" .. zone .. "Overlay", "image", "BlankZone")
end

function TacticsUi.setSpecialTacticsZone(color, zone)
  local imageSize = 85
  local paddingSize = 5
  local numZones = 7 + TableUtils.len(TacticsBoard.specialTactics)

  UI.setAttribute("tacticsPanelBottom__wrp" .. color, "active", true)
  UI.setAttribute("tacticsPanelSide__wrp" .. color, "active", true)

  UI.setAttribute("tacticsPanelBottom__wrp" .. color .. "Overlay", "active", true)
  UI.setAttribute("tacticsPanelSide__wrp" .. color .. "Overlay", "active", true)

  UI.setAttribute("tacticsPanelBottom", "width", numZones * imageSize + (numZones - 1) * paddingSize)
  UI.setAttribute("tacticsPanelSide", "height", numZones * imageSize + (numZones - 1) * paddingSize)

  UI.setAttribute("tacticsPanelBottom__" .. color, "image", zone)
  UI.setAttribute("tacticsPanelSide__" .. color, "image", zone)

  UI.setAttribute("tacticsPanelBottom__" .. color .. "Overlay", "image", zone)
  UI.setAttribute("tacticsPanelSide__" .. color .. "Overlay", "image", zone)
end

return {TacticsBoard, TacticsUi}
end)
__bundle_register("lua.utils-ui", function(require, _LOADED, __bundle_register, __bundle_modules)
local TableUtils = require("lua.utils-table")
local Utils = require("lua.utils")

local UiUtil = {}

function UiUtil.updatePlayerName(color)
  local name = UiUtil.getPlayerName(color)
  if name == color then
    name = name .. " Player"
  end
  UI.setValue(string.lower(color).."Player", UiUtil.getSafeName(name))
end

function UiUtil.toggleVisibilityStr(visibility, color)
    local split = Utils.split(visibility, "|")
    if TableUtils.hasValue(split, color) then
        local filtered = TableUtils.filter(split,
          function(e)
            return e ~= color
          end)
        return table.concat(filtered, "|")
    else
        table.insert(split, color)
        return table.concat(split, "|")
    end
end

function UiUtil.toggleVisibility(id, color)
    local visibilityString = self.UI.getAttribute(id, "visibility")
    self.UI.setAttribute(id, "visibility", UiUtil.toggleVisibilityStr(visibilityString, color))
end

function UiUtil.hide(id, color)
  if color == nil then
    self.UI.setAttribute(id, "visibility", "Hidden")
    return
  end

  local visibilityString = self.UI.getAttribute(id, "visibility")
  local split = Utils.split(visibilityString, "|")
  local filtered = TableUtils.filter(split, function(e) return e ~= color end)
  self.UI.setAttribute(id, "visibility", table.concat(filtered, "|"))
end

function UiUtil.show(id, color)
  if color == nil then
    self.UI.setAttribute(id, "visibility", "")
    return
  end

  local visibilityString = self.UI.getAttribute(id, "visibility")
  local split = Utils.split(visibilityString, "|")
  if not TableUtils.hasValue(split, color) then table.insert(split, color) end
  self.UI.setAttribute(id, "visibility", table.concat(split, "|"))
end

function UiUtil.getElementById(xmlTable, eleId)
  local found = nil
  for ix, ele in ipairs(xmlTable) do
    if ele.attributes ~= nil and ele.attributes.id == eleId then
      found = ele
      break
    end
    if ele.children then
      found = UiUtil.getElementById(ele.children, eleId)
    end
    if found ~= nil then
      break
    end
  end
  return found
end

function UiUtil.getSafeName(name)
  return name:gsub("\"", "'"):gsub("<", ""):gsub(">", "")
end

function UiUtil.getPlayerName(color)
  local out = color
  local player = Player[color]
  if player.steam_name ~= nil and player.steam_name ~= "" then
      out = player.steam_name
  end
  return UiUtil.getSafeName(out)
end

function UiUtil.redraw()
  log("Redrawing UI...")
  UI.setXml(UI.getXml())
end

return UiUtil
end)
