DiceTray = {}
DiceTray.__index = DiceTray
DiceTray.__className = "DiceTray"

setmetatable(DiceTray, {
    __index = GameObjectClass,
    __call = function(cls, gameObj, opts)
        opts = opts or {}
        local this = setmetatable(GameObjectClass(gameObj, cls.__className), DiceTray)

        this.color = opts.color
        this.defaultHouse = opts.defaultHouse
        this.DICE_TYPE_TO_DEFAULT = {
            ["Community"] = "CMON",
            ["TSL"] = "B For Better",
            ["World Cup"] = "World Cup",
        }

        this.zone = opts.zone

        this.diceType = nil
        this.selectedDie = nil
        this.textures = {}

        this.target = 4
        this.amount = 0
        this.maxAmount = 17

        this._isInitialized = false
        this._timer = nil
        return this
    end
})

function DiceTray:getSaveState(opts)
    opts = opts or {}
    local state = {
        color = self.color,
        defaultHouse = self.defaultHouse,
        target = self.target,
        amount = self.amount,
        diceType = self.diceType,
        selectedDie = self.selectedDie,
        zone = self.zone,
        class = self.__className,
    }
    if opts.isCreatingCopy then
        state.amount = 0
        state.zone = nil
    end
    return state
end
function DiceTray:restoreSaveState(savedData)
    self.color = savedData.color
    self.defaultHouse = savedData.defaultHouse
    self.zone = savedData.zone
    self.target = savedData.target
    self.amount = savedData.amount
    self.diceType = savedData.diceType
    self.selectedDie = savedData.selectedDie

    self:setTextures()
    self:updateTextures()
    self:setTarget(self.target)
    self:setAmount(self.amount)

    if self._isInitialized ~= true then
        self:init()
    end
end

function DiceTray:populateDropdownOptions()
    local xml = self.gameObj.UI.getXmlTable()
    for diceType, selectId in pairs(DICE_TYPE_TO_ID) do
        local select = UiUtil.getElementById(xml, selectId)
        local keys = TableUtils.filter(TableUtils.keys(TEXTURES), function(n) return TEXTURES[n].category == diceType end)
        local sortedKeys = table.sort(keys, function (a, b)
            local sortA = TEXTURES[a].sort or 0
            local sortB = TEXTURES[b].sort or 0
            if sortA ~= sortB then
                return sortA < sortB
            end
            return a < b
        end)
        local defaultSelect = self.DICE_TYPE_TO_DEFAULT[diceType] or self.defaultHouse
        select.children = TableUtils.map(sortedKeys, function(key)
            local rendered = {tag = "Option", value = key}
            if key == defaultSelect then
                rendered.attributes = {selected = true}
            end
            return rendered
        end)
    end

    self.gameObj.UI.setXmlTable(xml)
end
function DiceTray:updateChampionshipDiceSelect()
    local steam_id = Player[self.color].steam_id
    local xml = self.gameObj.UI.getXmlTable()

    local select_type = UiUtil.getElementById(xml, ID_DICE_TYPE_SELECT)
    select_type.children = TableUtils.map(TableUtils.keys(DICE_TYPE_TO_ID), function(key)
        local rendered = {tag = "Option", value = key}
            if key == "House" then
                rendered.attributes = {selected = true}
            end
            return rendered
    end)

    if ACCOUNTS_CHAMPIONS[steam_id] then
        table.insert(select_type.children, {tag = "Option", value = "Champion"})
    else
        self.DICE_TYPE_TO_DEFAULT["Champion"] = nil
        self.gameObj.UI.setXmlTable(xml)
        if self.diceType == "Champion" then Wait.frames(function() self:onDiceTypeDropDown_ValueChanged({1, "House", 3}) end, 5) end
        return
    end

    local select_champion = UiUtil.getElementById(xml, ID_CHAMPION_DICE_SELECT)
    local allowed_options = TableUtils.filter(TableUtils.keys(TEXTURES), function(texture_name)
        return TEXTURES[texture_name].category == "Champion" and TableUtils.hasValue(TEXTURES[texture_name].accounts, steam_id)
    end)
    select_champion.children = TableUtils.map(allowed_options, function(opt) return {tag = "Option", value = opt} end)
    select_champion.children[1].attributes = {selected = true}
    self.DICE_TYPE_TO_DEFAULT["Champion"] = select_champion.children[1].value
    self.gameObj.UI.setXmlTable(xml)
end

function DiceTray:createScriptingZone()
    local objSize = self.gameObj.getBounds().size
    local zone = getObjectFromGUID(self.zone)
    if zone == nil then
        zone = spawnObject({
            type = "ScriptingTrigger",
            position = self.gameObj.positionToWorld({0, 9, 0}),
            rotation = self.gameObj.getRotation() + Vector(0, -90, 0),
            scale = {objSize.x - 3, 40, objSize.z - 3},
        })
    end
    self.zone = zone.guid

    local onObjectLeave = function (params)
        local zone, obj = unpack(params)
        if zone.guid ~= self.zone then
            return
        end
        if obj.held_by_color or obj.type ~= "Dice" then
          return
        end
        obj.setVelocity(obj.getVelocity():rotateOver("y", 180))
    end
    EventUtils.register("onObjectLeaveZone", onObjectLeave)
end
function DiceTray:setZonePosition()
    local zone = getObjectFromGUID(self.zone)
    zone.setPosition(self.gameObj.positionToWorld({0, 9, 0}))
    zone.setRotation(self.gameObj.getRotation() + Vector(0, -90, 0))
end

function DiceTray:init()
    self._isInitialized = true
    self:populateDropdownOptions()
    -- Thanks to TTS UI implementation, we would get stale XML data if we ran this function immediately
    Wait.frames(function() self:updateChampionshipDiceSelect() end, 3)
    EventUtils.register("onPlayerChangedColor", function(params)
        self:updateChampionshipDiceSelect()
    end)
    self:createScriptingZone()
    self:initUiEventListeners()
    self:setTextures()

    self._timer = Wait.time(function()
        local dice = self:getDice()
        if not TableUtils.all(dice, function(d) return d.resting end) then
            return
        end
        self:sort()
    end, 0.25, -1)
end
function DiceTray:initUiEventListeners()
    self:register({"onIncreaseDice_Click", "onDecreaseDice_Click", "onDiceCount_ValueChanged"})
    self:register({"onIncreaseTarget_Click", "onDecreaseTarget_Click", "onTargetNumber_ValueChanged"})
    self:register({"onRollDice_Click", "onRollMisses_Click", "onRollHits_Click"})
    self:register({"onDiceTypeDropDown_ValueChanged", "onSelectDie_ValueChanged"})
    self:register({"onRemovePanicDice_Click", "onRollPanicDice_Click"})
    self:register({"onShowPanel_Click", "onHidePanel_Click"})
end
function DiceTray:onDestroy()
    if self._timer ~= nil then
        Wait.stop(self._timer)
    end
    gameObjects[self._guid] = nil
end

function DiceTray:getTargetSliderValue()
    return tonumber(self.gameObj.UI.getAttribute("targetNumberSlider", "value"))
end
function DiceTray:getAmountSliderValue()
    return tonumber(self.gameObj.UI.getAttribute("diceCountSlider", "value"))
end

function DiceTray:onIncreaseDice_Click()
    local amount = self:getAmountSliderValue()
    self:setAmount(math.min(amount + 1, self.maxAmount))
end
function DiceTray:onDecreaseDice_Click()
    local amount = self:getAmountSliderValue()
    self:setAmount(math.max(amount - 1, 0))
end
function DiceTray:onDiceCount_ValueChanged(params)
    local player, value, id = unpack(params)
    self:setAmount(tonumber(value))
end

function DiceTray:onIncreaseTarget_Click()
    local target = self:getTargetSliderValue()
    self:setTarget(math.min(target + 1, 6))
end
function DiceTray:onDecreaseTarget_Click()
    local target = self:getTargetSliderValue()
    self:setTarget(math.max(target - 1, 2))
end
function DiceTray:onTargetNumber_ValueChanged(params)
    local player, value, id = unpack(params)
    self:setTarget(tonumber(value))
end

function DiceTray:setTarget(target)
    self.target = target
    self.gameObj.UI.setValue("targetNumberLabel", "Target  " .. target)
    self.gameObj.UI.setAttribute("targetNumberSlider", "value", target)

    self:countSuccesses()
end
function DiceTray:setAmount(amount)
    self.amount = amount
    self.gameObj.UI.setValue("diceCountLabel", "Dice  " .. amount)
    self.gameObj.UI.setAttribute("diceCountSlider", "value", amount)

    local dice = self:getDice()
    local len = #dice
    for ix = amount + 1, len do
        dice[ix].destruct()
    end
    local spawnGrid = Grid({
        origin = self.gameObj.positionToWorld({-4, 0, -5}),
        columns = self.maxAmount,
        rows = 1,
        rowOffset = self.gameObj.getTransformRight() * -1.1,
        columnOffset = self.gameObj.getTransformForward() * 1.1,
    })
    for ix = len + 1, amount do
        local pos = spawnGrid:posFromIx(ix)
        self:spawnDie(pos)
    end
end

function DiceTray:onRollDice_Click()
    local dice = self:getDice({includePanicDice = true})
    self:onClick_doRoll(dice)
end
function DiceTray:onRollMisses_Click()
    local dice = self:getDice({failures = true})
    self:onClick_doRoll(dice)
end
function DiceTray:onRollHits_Click()
    local dice = self:getDice({successes = true})
    self:onClick_doRoll(dice)
end
function DiceTray:onClick_doRoll(diceToRoll)
    Wait.condition(
        function()
            Wait.time(function() self:doRoll(diceToRoll) end, 0.4)
        end,
        function()
            return TableUtils.all(diceToRoll, function(d) return d.resting end)
        end,
        1 -- timeout after seconds
    )
end
-- opts.includePanicDice
-- opts.resting: only get resting dice
-- opts.successes: only get successes
-- opts.failures: only get failures
function DiceTray:getDice(opts)
    opts = opts or {}
    local zone = getObjectFromGUID(self.zone)
    if zone == nil then
        return {}
    end
    return TableUtils.filter(zone.getObjects(), function (obj, key)
        if obj.type ~= "Dice" then
            return false
        end
        if not opts.includePanicDice and obj.hasTag("PanicDice") then
            return false
        end
        if opts.resting and not obj.resting then
            return false
        end
        if opts.successes and obj.getValue() < self.target then
            return false
        end
        if opts.failures and obj.getValue() >= self.target then
            return false
        end
        return true
    end)
end
function DiceTray:spawnDie(position, value)
    local newDie = nil
    if self.textures.is3d then
        local objParameters = {
            type = "Custom_Assetbundle",
            position = position,
            scale = {x=0.53, y=0.53, z=0.53}
        }
        newDie = spawnObject(objParameters)
        newDie.setCustomObject({
            assetbundle = self.textures.dice,
            type = 2,
            -- TODO: Allow for dynamic material
            material = 2,
        })
    else
        local objParameters = {
            type = "Custom_Dice",
            position = position,
            scale = {x=1.60, y=1.60, z=1.60}
        }
        newDie = spawnObject(objParameters)
        local texture = self.textures.dice
        if type(texture) == "function" then
            texture = texture()
        end
        newDie.setCustomObject({image = texture, type = 1})
    end
    local rotValues = self.textures.rotValues or d6RotationValues
    newDie.setRotationValues(rotValues)
    local toSetValue = value or math.random(1, 6)
    Wait.frames(function()
        newDie.setValue(toSetValue)
    end, 3)
end
function DiceTray:doRoll(diceToRoll)
    for _, die in pairs(diceToRoll) do
        die.setLock(false)
        die.randomize()
        Wait.frames(function() Global.call("castDie", die) end, 1)
    end
end
function DiceTray:sort()
    local dice = self:getDice({resting = true})
    local grids = {}
    for ix = 1, 6 do
        grids[ix] = Grid({
            origin = self.gameObj.positionToWorld({-4.5 + ix * 1.32, -0.12, -3.5}),
            columns = 20,
            rows = 1,
            rowOffset = self.gameObj.getTransformRight() * -1.3,
            columnOffset = self.gameObj.getTransformForward() * 1.3,
        })
    end
    local trayRot = self.gameObj.getRotation()
    for _, die in pairs(dice) do
        local value = die.getValue()
        local gridPos = grids[value]:getNextPos()
        local pos = die.getPosition()
        die.setPosition({gridPos.x, pos.y, gridPos.z})
        local rot = die.getRotation()
        die.setRotation({Utils.round(rot.x / 90) * 90, trayRot.y + 90, Utils.round(rot.z / 90) * 90})
    end
    for val = 1, 6 do
        local count = grids[val]._ix
        local countText = ""
        if count ~= 0 then
            countText = "#" .. val .. ": " .. count
        end
        self.gameObj.UI.setAttribute("resultLabel" .. val, "text", countText)
    end

    self:countSuccesses()
end
function DiceTray:countSuccesses()
    local dice = self:getDice({resting = true})
    if #dice == 0 then
        self.gameObj.UI.setAttribute("totalResultLabel", "text", " ")
    else
        local numSuccesses = TableUtils.count(dice, function (die) return die.getValue() >= self.target end)
        self.gameObj.UI.setAttribute("totalResultLabel", "text", numSuccesses .. " / " .. #dice)
    end
end

function DiceTray:onDiceTypeDropDown_ValueChanged(params)
    local player, type, id = unpack(params)
    self.diceType = type
    self.selectedDie = nil
    self.gameObj.UI.setAttribute("selectDie", "active", type == "House")
    self.gameObj.UI.setAttribute("selectCommunityDie", "active", type == "Community")
    self.gameObj.UI.setAttribute("selectTslDie", "active", type == "TSL")
    self.gameObj.UI.setAttribute("selectWorldCupDie", "active", type == "World Cup")
    self.gameObj.UI.setAttribute("selectChampionDie", "active", type == "Champion")

    self:setTextures()
    self:updateTextures()
end
function DiceTray:onSelectDie_ValueChanged(params)
    local player, selection, id = unpack(params)
    self.selectedDie = selection

    self:setTextures()
    self:updateTextures()
end

function DiceTray:setTextures()
    local type = self.diceType or "House"
    local selected = self.selectedDie or self.DICE_TYPE_TO_DEFAULT[type] or self.defaultHouse or "CMON"
    self.textures = TEXTURES[selected]
    self.diceType = type
    self.selectedDie = selected
end
function DiceTray:updateTextures()
    local dice = self:getDice()
    for _, die in pairs(dice) do
        local pos = die.getPosition()
        local val = die.getValue()
        die.destruct()
        self:spawnDie(pos, val)
    end

    if self.textures.decal ~= nil then
        local rawScale = self.textures.scale or 8
        self.gameObj.setDecals({
            {
                name = "Decal",
                url = self.textures.decal,
                position = {0, -0.36, 0},
                rotation = {90, 270, 0},
                scale    = {rawScale, rawScale, rawScale},
            },
        })
    else
        self.gameObj.setDecals({})
    end
    self:destroyPanicDice(true)
end

function DiceTray:spawnPanicDie(position)
    local newDie = nil
    if self.textures.panic == nil then
        newDie = spawnObject({
            type = "Die_6",
            position = position,
            scale = {x=1.60, y=1.60, z=1.60}
        })
        newDie.setColorTint({r = 0.67, g = 0.0039, b = 0})
    elseif self.textures.is3d then
        local objParameters = {
            type = "Custom_Assetbundle",
            position = position,
            scale = {x=0.53, y=0.53, z=0.53}
        }
        newDie = spawnObject(objParameters)
        newDie.setCustomObject({
            assetbundle = self.textures.panic,
            type = 2,
            -- TODO: Allow for dynamic material
            material = 0,
        })
    else
        newDie = spawnObject({
            type = "Custom_Dice",
            position = position,
            scale = {x=1.60, y=1.60, z=1.60}
        })
        local texture = self.textures.panic
        if type(texture) == "function" then
            texture = texture()
        end
        newDie.setCustomObject({
            image = texture,
            type = 1
        })
    end
    newDie.setName("Panic")
    local rotValues = self.textures.rotValues or d6RotationValues
    newDie.setRotationValues(rotValues)
    -- newDie.setValue(6)
    newDie.setTags({"PanicDice", self.color})
    return newDie
end
function DiceTray:spawnPanicD3(position)
    local d3 = nil
    if self.textures.is3d then
        local objParameters = {
            type = "Custom_Assetbundle",
            position = position,
            rotation = d3RotationValues[3].rotation,
            scale = {x=0.53, y=0.53, z=0.53}
        }
        d3 = spawnObject(objParameters)
        d3.setCustomObject({
            assetbundle = self.textures.d3,
            type = 2,
            material = 0,
        })
    else
        d3 = spawnObject({
            type = "Custom_Dice",
            position = position,
            rotation = d3RotationValues[3].rotation,
            scale = {x=1.60, y=1.60, z=1.60}
        })
        local d3_image = self.textures.d3 or "http://cloud-3.steamusercontent.com/ugc/1035211586490238967/AC2D7342236B216FA0BD9752F275D02517C52584/"
        d3.setCustomObject({
            image = d3_image,
            type = 1
        })
    end
    d3.setName("D3")
    d3.setRotationValues(d3RotationValues)
    -- d3.setValue(2)
    d3.setTags({"PanicDice", self.color})
    return d3
end
function DiceTray:destroyPanicDice(respawn)
    local panicDice = getObjectsWithAllTags({"PanicDice", self.color})

    for _, die in pairs(panicDice) do
        local pos = die.getPosition()
        local name = die.getName()
        die.destruct()
        if respawn ~= nil then
            if name == "D3" then
                self:spawnPanicD3(pos)
            else
                self:spawnPanicDie(pos)
            end
        end
    end
end
function DiceTray:onRemovePanicDice_Click()
    self:destroyPanicDice()
end
function DiceTray:onRollPanicDice_Click()
    self:destroyPanicDice()

    local panicDice = {}
    local d3 = self:spawnPanicD3(self.gameObj.positionToWorld({2.5, 0, 4}))
    table.insert(panicDice, d3)
    for ix = 1, 2 do
        local newDie = self:spawnPanicDie(self.gameObj.positionToWorld(({2.5 - ix, 0, 4})))
        table.insert(panicDice, newDie)
    end

    Wait.frames(function()
        Wait.condition(
            function()
                self:doRoll(panicDice)
            end,
            function()
                return TableUtils.all(panicDice, function(d) return d.resting end)
            end)
    end, 10)
end


function DiceTray:onShowPanel_Click()
    self.gameObj.UI.setAttribute("toggleRollerPanel", "active", "false")
    self.gameObj.UI.show("diceRollingPanel")
    self.gameObj.UI.show("diceTargetPanel")
end
function DiceTray:onHidePanel_Click()
    self.gameObj.UI.hide("diceTargetPanel")
    self.gameObj.UI.hide("diceRollingPanel")
    self.gameObj.UI.setAttribute("toggleRollerPanel", "active", "true")
end

function DiceTray.initDiceTrays()
    local blueTray = getObjectFromGUID(GUIDS["dice_tray"]["Blue"])
    local redTray = getObjectFromGUID(GUIDS["dice_tray"]["Red"])

    local diceTrayBlue = DiceTray(blueTray, {
        color = "Blue",
        defaultHouse = "Stark",
        zone = GUIDS["dice_tray_zone"]["Blue"],
    })

    local diceTrayRed = DiceTray(redTray, {
        color = "Red",
        defaultHouse = "Lannister",
        zone = GUIDS["dice_tray_zone"]["Red"],
    })
    diceTrayBlue:init()
    diceTrayRed:init()
end

end)
__bundle_register("lua.faction-spawner", function(require, _LOADED, __bundle_register, __bundle_modules)
local Utils = require("lua.utils")
local TableUtils = require("lua.utils-table")
local db = require("lua.data-lookup")

local FACTION_CATEGORIES = {
    ["cmon"] = "CMON - Official",
    ["brew"] = "Homebrew"
}

FactionSpawner = {}
FactionSpawner.__index = FactionSpawner
FactionSpawner.__className = "FactionSpawner"

setmetatable(FactionSpawner, {
    __index = Spawner,
    __call = function(cls, gameObj, opts)
        opts = opts or {}
        opts.__className = cls.__className
        local this = setmetatable(Spawner(gameObj, opts), FactionSpawner)
        this.selectedColor = "Orange"
        this.onClick_spawnThrottled = Utils.throttle(this.onClick_spawn, 7)
        this.gridOrigins = opts.gridOrigins
        this.category = FACTION_CATEGORIES.cmon
        return this
    end
})

function FactionSpawner:init()
    self:initUiEventListeners()
    local customAssets = self:getCustomAssets()
    self.gameObj.UI.setCustomAssets(customAssets)
    self:createXmlUi()
    self:initSpawnGrids()
end
function FactionSpawner:initUiEventListeners()
    self:register({"onClick_spawnThrottled", "onClick_clear", "onClick_cat"})
end
function FactionSpawner:createXmlUi()
    local getButton = function(factionMeta)
        return {
            tag = "Button",
            attributes = {
                id = "btn_spawn_"..factionMeta.name,
                iconWidth = 28,
                color = "#FFFFFF00",
                icon = factionMeta.name,
                onclick = "onClick_spawnThrottled(" .. factionMeta.name .. ")",
            },
        }
    end
    local factionsToSpawn = TableUtils.filter(self.factions, function(m) return m.category == self.category end)
    local spawnButtons = TableUtils.map(factionsToSpawn, getButton)
    local grid = {
        {
            tag = "GridLayout",
            attributes = {
                position = "0 0 -30",
                rotation = "0 0 180",
                width = 150,
                cellSize = "30 30",
                padding = "15 15 15 15",
                height = 150,
            },
            children = spawnButtons
        },
        {
            tag = "Button",
            attributes = {
                id = "btn_cat",
                onclick = "onClick_cat",
                position = "0 60 -30",
                rotation = "0 0 180",
                width = 130,
                height = 20,
                text = self.category,
                colors="#000000|rgba(0.3,0.3,0.3,1)|rgba(0.3, 0.3, 0.3, 1.0)|#000000",
                textColor="#FFFFFF"
            }
        },
        {
            tag = "Button",
            attributes = {
                id = "btn_clear",
                onclick = "onClick_clear",
                position = "0 80 -30",
                rotation = "0 0 180",
                width = 130,
                height = 20,
                text = "Clear Area",
                colors="#000000|rgba(0.3,0.3,0.3,1)|rgba(0.3, 0.3, 0.3, 1.0)|#000000",
                textColor="#FFFFFF"
            }
        }
    }
    self.gameObj.UI.setXmlTable(grid)
end
function FactionSpawner:onClick_cat()
    if self.category == FACTION_CATEGORIES.cmon then
        self.category = FACTION_CATEGORIES.brew
    else
        self.category = FACTION_CATEGORIES.cmon
    end

    self:createXmlUi()
end

function FactionSpawner:getCustomAssets()
    local assets = {}

    for _, faction in ipairs(self.factions) do
        table.insert(assets, {name = faction.name, url = faction.image})
    end

    return assets
end

-- This only gets called with throttle
-- params = {player, faction, alt_click}
function FactionSpawner:onClick_spawn(params)
    local player, faction, altClick = unpack(params)
    local found = TableUtils.find(self.factions, function(f) return f.name == faction end)
    if found then
        self.selectedColor = found.color
    end
    self:doClear()
    broadcastToColor("Spawning " .. faction.. "...", player.color)
    local factionUnits = self:getFactionUnits(faction)
    self:initSpawnGrids()
    local co = coroutine.create(function()
        self:doSpawn(factionUnits)
        self:spawnTactics(faction)
        self:spawnSpecials(factionUnits)
    end)
    coroutine.resume(co)
    local ix = 0
    local lagFactor = 3 -- increasing this will make the game lag less but for longer
    Wait.condition(
        function()
            broadcastToColor("Spawned " .. faction.. "!", player.color)
        end,
        function()
            if ix % lagFactor == 0 and coroutine.status(co) == "suspended" then
                coroutine.resume(co)
            end
            ix = ix + 1
            return coroutine.status(co) == "dead"
        end
    )
end
-- call this as a coroutine
function FactionSpawner:doSpawn(factionUnits)
    for _, key in ipairs({"unit", "commander", "attachment", "enemy", "ncu"}) do
        if factionUnits[key] == nil then
            factionUnits[key] = {}
        end
    end

    for _, unit in ipairs(factionUnits.unit) do
        local name = unit.fullName
        if not pcall(function()
            local pos = self.grid_combatUnits:getNextPos()
            local defs = self:combatUnitFromLookup(unit)
            local tray = self:doSpawnCombatUnit({
                position = pos,
                rotation = self.rotUp + Vector(0, 180, 0),
                trayClass = defs.trayClass,
                objectData = defs.objectData,
                spawnOptions = defs.spawnOptions,
            })
            for _, card in pairs(defs.cards) do
                self:doSpawnCardAndTokens({card = card, position = pos + self.vectUp * -4.6, rotation = self.rotUp})
            end
        end) then
            broadcastToAll("Error while spawning " .. name, "Red")
        end
        coroutine.yield()
    end

    for _, cmdr in ipairs(factionUnits.commander) do
        local name = cmdr.fullName
        if not pcall(function()
            local pos = self.grid_commanders:getNextPos()
            local trayClass = self:getTrayClass(cmdr.tray)
            local defs
            if cmdr.type == "ncu" then
                pos = pos + self.vectUp
                defs = self:figureFromLookup(cmdr, {
                    assetScale = {2.6, 2.6, 2.6},
                    figureScale = {1.75, 1.75, 1.75},
                })
            else
                defs = self:figureFromLookup(cmdr, {
                    assetScale = {1, 1, 1},
                    figureScale = {trayClass.figureScale, trayClass.figureScale, trayClass.figureScale},
                })
            end
            defs.objectData.position = pos
            defs.objectData.rotation = self.rotUp
            local fig = self:doSpawnFigure({
                name = defs.name,
                description = defs.description,
                objectData = defs.objectData,
                custom = defs.custom,
                color = self.colorLookup[self.selectedColor]
            })
            if cmdr.type == "ncu" then
                fig.addTag("NCU")
                pos = pos - self.vectUp
            else
                fig.addTag(trayClass.unitModelTag)
                fig.addTag(GenericUnitTray.unitModelTag)
            end
            local cardPos = pos + self.vectUp * -2.6

            local cmdr_tactics
            -- FIXME/TODO: Clear up this garbage
            if name == "Areo Hotah - Captain of The Guard" then
                cmdr_tactics = db.get("30901").tacticsCards
            else
                cmdr_tactics = cmdr.tacticsCards
            end
            local tactics = {}
            for _, card in pairs(cmdr_tactics) do
                table.insert(tactics, card)
                table.insert(tactics, card)
            end
            -- TODO: set flag in data instead of hardcoding it here
            local commanderIsSoloUnit = cmdr.name == "Mag the Mighty" or cmdr.name == "Varamyr Sixskins"
            -- Spawn the unit card first: its size gets shrunk to the size of the cards above
            if commanderIsSoloUnit then
                for ix, card in pairs(defs.cards) do
                    self:doSpawnCardAndTokens({card = card, position = cardPos + Vector(0, 0.05 * ix, 0), rotation = self.rotUp})
                end
                self:spawnDeckOfCards({
                    cards = tactics,
                    back = tacticsCardBack,
                    position = cardPos + Vector(0, 0.1, 0),
                    rotation = self.rotUp,
                    tags = {"TacticsCard"},
                })
            -- normally we want the attachment card ontop
            else
                self:spawnDeckOfCards({
                    cards = tactics,
                    back = tacticsCardBack,
                    position = cardPos,
                    rotation = self.rotUp,
                    tags = {"TacticsCard"},
                })
                for ix, card in pairs(defs.cards) do
                    self:doSpawnCardAndTokens({card = card, position = cardPos + Vector(0, 0.5 + 0.05 * ix, 0), rotation = self.rotUp})
                end
            end
        end) then
            broadcastToAll("Error while spawning " .. name, "Red")
        end
        coroutine.yield()
    end

    for _, attachmentType in ipairs({"attachment", "enemy"}) do
        for _, attch in ipairs(factionUnits[attachmentType]) do
            local name = attch.fullName
            if not pcall(function()
                local pos = self.grid_attachments:getNextPos()
                local trayClass = self:getTrayClass(attch.tray)
                local defs = self:figureFromLookup(attch, {
                    assetScale = {1, 1, 1},
                    figureScale = {trayClass.figureScale, trayClass.figureScale, trayClass.figureScale},
                })
                defs.objectData.position = pos
                defs.objectData.rotation = self.rotUp
                local fig = self:doSpawnFigure({
                    name = defs.name,
                    description = defs.description,
                    objectData = defs.objectData,
                    custom = defs.custom,
                    color = self.colorLookup[self.selectedColor]
                })
                fig.addTag(trayClass.unitModelTag)
                fig.addTag(GenericUnitTray.unitModelTag)
                local cardPos = pos + self.vectUp * -2.6
                for ix, card in pairs(defs.cards) do
                    self:doSpawnCardAndTokens({card = card, position = cardPos + Vector(0, 0.05, 0) * ix, rotation = self.rotUp})
                end
            end) then
                broadcastToAll("Error while spawning " .. name, "Red")
            end
        end
        coroutine.yield()
    end

    for _, ncu in ipairs(factionUnits.ncu) do
        local name = ncu.fullName
        if not pcall(function()
            local pos = self.grid_ncus:getNextPos()
            local defs = self:figureFromLookup(ncu, {
                assetScale = {2.6, 2.6, 2.6},
                figureScale = {1.75, 1.75, 1.75},
            })

            defs.objectData.position = pos
            defs.objectData.rotation = self.rotUp
            local fig = self:doSpawnFigure({
                name = defs.name,
                id = defs.id,
                description = defs.description,
                objectData = defs.objectData,
                custom = defs.custom,
                color = self.colorLookup[self.selectedColor]
            })
            fig.addTag("NCU")

            local cardPos = pos + self.vectUp * -3.6
            if defs.specialTactics then
                local tacticsBoard = self:doSpawnCard({
                    card = defs.specialTactics,
                    position = cardPos,
                    rotation = self.rotUp,
                })
                if(tacticsBoard) then
                    tacticsBoard.setSnapPoints({{
                        position = {0, 0, -0.85},
                        rotation = {0, 0, 0},
                        rotation_snap = true
                    }})
                end
            end
            local lastSpawned = nil
            for ix, card in pairs(defs.cards) do
                lastSpawned = self:doSpawnCardAndTokens({card = card, position = cardPos + Vector(0, 0.05, 0) * ix, rotation = self.rotUp})
            end
            lastSpawned.addTag("NCUcard")
        end) then
            broadcastToAll("Error while spawning " .. name, "Red")
        end

        coroutine.yield()
    end
end
function FactionSpawner:spawnTactics(faction)
    local baseCards = db.get_baseDeck(faction)
    local cards = {}
    for _, card in pairs(baseCards) do
        table.insert(cards, card)
        table.insert(cards, card)
    end
    local deck = self:spawnDeckOfCards({
        cards = cards,
        back = tacticsCardBack,
        position = self.grid_commanders:getNextPos() + self.vectUp * -2.6,
        rotation = self.rotUp,
        tags = {"TacticsCard"},
    })
end
function FactionSpawner:spawnSpecials(factionUnits)
    local cards = factionUnits.special or {}
    local spawned = self:spawnDeckOfCards({
        cards = TableUtils.map(cards, function(c) return {name = c.name, face = c.cardFace, back = c.cardBack} end),
        position = self.grid_commanders:getNextPos() + self.vectUp * -2.6,
        rotation = self.rotUp,
    })
end

function FactionSpawner:combatUnitFromLookup(lookup)
    local figures = {}
    local unitFigure = {}
    local trayClass = self:getTrayClass(lookup.tray)
    local name = lookup.fullName

    local specialFigures = self:getSpecialRuleFromType(lookup, "banners")
    for idx = 1, (trayClass.rows * trayClass.columns), 1 do
        if specialFigures ~= nil and idx > 8 then
            unitFigure = self:getUnitFigureData(specialFigures)
            table.insert(figures, unitFigure)
        else
            unitFigure = self:getUnitFigureData(lookup)
            table.insert(figures, unitFigure)
        end
    end

    for idx, figure in ipairs(figures) do
        figure.Transform.posX = figure.Transform.posX + trayClass.snapPoints[idx].Position.x
        figure.Transform.posY = figure.Transform.posY + trayClass.snapPoints[idx].Position.y
        figure.Transform.posZ = figure.Transform.posZ + trayClass.snapPoints[idx].Position.z
        figure.Memo = idx
    end

    local cards = self:getUnitCards(lookup)

    local objectData = trayClass:getObjectData({
        ChildObjects = figures,
        Nickname = name,
        color = self.colorLookup[self.selectedColor]
    })

    local spawnOptions = self:getCombatUnitSpawnOptions(lookup, nil)

    return {
        objectData = objectData,
        spawnOptions = spawnOptions,
        cards = cards,
        trayClass = trayClass
    }
end

function FactionSpawner:getFactionUnits(faction)
    local factionLookup = db.get_faction(faction)
    local factionUnits = {}
    for _, item in pairs(factionLookup) do
        local type = item.type
        if item.enemy then
            type = "enemy"
        end
        if item.cmdr then
            type = "commander"
        end
        if type ~= nil then
            type = type:lower()
            if factionUnits[type] == nil then
                factionUnits[type] = {}
            end
            table.insert(factionUnits[type], item)
        end
    end
    return factionUnits
end

function FactionSpawner:onClick_clear()
    self:doClear()
end

function FactionSpawner:doClear()
    self.grid_combatUnits:clear()
    self.grid_commanders:clear()
    self.grid_attachments:clear()
    self.grid_ncus:clear()
end


function FactionSpawner.initSpawners()
    local blueSpawner = getObjectFromGUID(GUIDS["faction_spawner"]["Blue"])
    local redSpawner = getObjectFromGUID(GUIDS["faction_spawner"]["Red"])
    local blueObj = FactionSpawner(blueSpawner, {
        vectUp = Vector(0, 0, 1),
        vectRight = Vector(1, 0, 0),
        rotUp = Vector(0, 180, 0),
        gridOrigins = {
            ncus = Vector(-137, 2.5, -50),
            combatUnits = Vector(-136, 2.5, -5),
            commanders = Vector(-137, 2.5, -43),
            attachments = Vector(-137, 2.5, -32),
        }
    })
    blueObj:init()
    local redObj = FactionSpawner(redSpawner, {
        vectUp = Vector(0, 0, -1),
        vectRight = Vector(-1, 0, 0),
        rotUp = Vector(0, 0, 0),
        gridOrigins = {
            ncus = Vector(-137, 2.5, 50),
            combatUnits = Vector(-136, 2.5, 5),
            commanders = Vector(-137, 2.5, 43),
            attachments = Vector(-137, 2.5, 32),
        }
    })
    redObj:init()
end

function FactionSpawner:initSpawnGrids()
    self.grid_ncus = Grid({
        origin = self.gridOrigins.ncus,
        rowOffset = self.vectUp * -8,
        columnOffset = Vector(1, 0, 0) * 3.6,
        columns = 12,
        rows = 2,
    })
    self.grid_combatUnits = Grid({
        origin = self.gridOrigins.combatUnits,
        rowOffset = self.vectUp * -9,
        columnOffset = Vector(1, 0, 0) * 5.7,
        columns = 10,
        rows = 3,
    })
    self.grid_commanders = Grid({
        origin = self.gridOrigins.commanders,
        rowOffset = self.vectUp * -6,
        columnOffset = Vector(1, 0, 0) * 2.7,
        columns = 18,
        rows = 1,
    })
    self.grid_attachments = Grid({
        origin = self.gridOrigins.attachments,
        rowOffset = self.vectUp * -6,
        columnOffset = Vector(1, 0, 0) * 2.7,
        columns = 20,
        rows = 2,
    })
end

