            position = "0 -25 -21",
            rotation = "0 0 180 ",
            width = "240",
            height = "41",
            fontSize = "20",
            fontStyle = "Bold",
            placeholder = self.source ==  "Text" and "Paste army text here" or "Paste army ID here",
            lineType = self.source ==  "Text" and "MultiLineNewLine" or "SingleLine"
        }
    }

    local xmlUiTable = {
        input,
        {
            tag = "Panel",
            attributes = {
                width = "240",
                height = "80",
                rotation = "0 0 180",
                position = "0 50 -21"
            },
            children = {{
            tag = "TableLayout",
            attributes = {
                cellSpacing = "10",
                cellBackgroundColor = "clear",
                columnWidths = "120 120"
            },
            children = {{
                tag = "Row",
                children = {{
                    tag = "Cell",
                    children = {{
                        tag = "Dropdown",
                        attributes = {
                            id = "chooseColorOption",
                            onValueChanged = self._guid .. "/chooseColor_onValueChanged",
                            colors = "#FFFFFF|#C0C0C0|#FFFFFF|A0A0A0",
                            width = "120",
                            height = "34",
                            fontSize = "17",
                            fontStyle = "Bold",
                            itemHeight = "34",
                            scrollSensitivity = "50"
                        },
                        children = colorOptions
                    }}
                }, {
                    tag = "Cell",
                    children = {{
                        tag = "Button",
                        attributes = {
                            id = "spawnArmyButton",
                            onclick = self._guid .. "/spawnArmy_onClick",
                            colors = "#FFFFFF|#C0C0C0|#FFFFFF|A0A0A0",
                            width = "120",
                            height = "34",
                            fontSize = "17",
                            fontStyle = "Bold",
                            text = "Spawn Army"
                        }
                    }}
                }}
            }, {
                tag = "Row",
                children = {{
                    tag = "Cell",
                    attributes = {
                        columnSpan = "2"
                    },
                    children = {{
                        tag = "ProgressBar",
                        attributes = {
                            id = "importProgressBar",
                            active = "false",
                            width = "240",
                            height = "34",
                            showPercentageText = "false",
                            color = "#FFFFFF",
                            fillImageColor = "#0094FF"
                        }
                    }, {
                        tag = "Dropdown",
                        attributes = {
                            id = "chooseSourceOption",
                            onValueChanged = self._guid .. "/chooseSource_onValueChanged",
                            colors = "#FFFFFF|#C0C0C0|#FFFFFF|A0A0A0",
                            width = "240",
                            height = "34",
                            fontSize = "17",
                            fontStyle = "Bold",
                            itemHeight = "34"
                        },
                        children = sourceOptions
                    }}
                }}
            }}
