        customAssets = {
            {
                image = "http://cloud-3.steamusercontent.com/ugc/2072258090093445189/CC4B317AF33299E75E9847A6EE6CC2F66A7C878E/",
                position = { 27.7, 0.76, 0 },
                scale = { 3.71, 1, 3.71 },
                rotation = { 0, 270, 0 },
