SETTINGS = {
    useClock = false,
    useSpectatorBlue = false,
    useSpectatorRed = false,
    clockInitialTime = 60, -- in minutes
    clockIncrement = 0, -- in minutes
    use3DMiniatures = true,
    background = "Open Ruin",
