        callback = function()
            -- do something?
        end
    }, {
        type = "dropdown",
        settingName = "language",
        name = "Language",
        tooltip = "Change the language of newly spawned cards.",
        options = { "en", "de", "fr" },
    }, {
        type = "dropdown",
        settingName = "patch",
        name = "Patch",
        tooltip = "Change the game version of newly spawned cards.",
        options = { "CMON: S07", "Custom Balance" },
        callback = function(_, value)
            if value == "CMON: S07" then
                DB.reset()
            elseif value == "Custom Balance" then
                DB.patch("cba")
            end
        end
    }, {
        type = "dropdown",
        settingName = "background",
